import ExcelJS from "exceljs";
import { downloadOutline } from "ionicons/icons";
import React, { useEffect, useState, useRef } from "react";
import {
  IonPage,
  IonHeader,
  IonToolbar,
  IonTitle,
  IonContent,
  IonGrid,
  IonRow,
  IonCol,
  IonButton,
  IonCard,
  IonCardContent,
  IonIcon,
} from "@ionic/react";
import axiosInstance from "../../config/axios";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { documentText } from "ionicons/icons";
import { Bar } from "react-chartjs-2";
import {
  Chart,
  CategoryScale,
  LinearScale,
  BarElement,
  Title as ChartTitle,
  Tooltip,
  Legend,
} from "chart.js";
import ChartDataLabels from "chartjs-plugin-datalabels";
import "./Reportes.css";

// Registrar componentes y plugins
Chart.register(
  CategoryScale,
  LinearScale,
  BarElement,
  ChartTitle,
  Tooltip,
  Legend,
  ChartDataLabels
);

interface ProductoMasPedido {
  nombre_indumentaria: string;
  codigoIndumentaria: string;
  cantidad_total_vendida: number;
  talle: string;
  tela: string;
  color: string;
}

const ProductosMasPedidos: React.FC = () => {
  const [productos, setProductos] = useState<ProductoMasPedido[]>([]);
  const [incluirGrafico, setIncluirGrafico] = useState(false);
  const chartRef = useRef<any>(null);
  const fechaEmision = new Date().toLocaleString("es-AR");

  useEffect(() => {
    axiosInstance
      .get("/api/reportes/productos-mas-pedidos")
      .then((res) => setProductos(res.data))
      .catch((error) => {
        console.error("Error al cargar productos más pedidos:", error);
        setProductos([]);
      });
  }, []);

  // Etiqueta combinada para cada producto
  const etiquetas = productos.map(
    (p) => `${p.nombre_indumentaria}, Talle ${p.talle}, ${p.tela}, ${p.color}`
  );

  // Genera un array de colores distintos (puedes personalizarlos)
  const colores = [
    "#FF6384", // rojo
    "#36A2EB", // azul
    "#FFCE56", // amarillo
    "#4BC0C0", // verde agua
    "#9966FF", // violeta
  ];

  // Datos para el gráfico
  const data = {
    labels: etiquetas,
    datasets: [
      {
        label: "Cantidad Vendida",
        data: productos.map((p) => p.cantidad_total_vendida),
        backgroundColor: colores.slice(0, productos.length), // Un color por barra
        borderRadius: 8,
        maxBarThickness: 32,
      },
    ],
  };

  const options = {
    indexAxis: "y" as const,
    responsive: true,
    plugins: {
      legend: { display: false },
      title: {
        display: true,
        text: "Top 10 Productos Más Pedidos",
        font: { size: 18 },
        padding: { top: 10, bottom: 20 },
      },
      datalabels: {
        anchor: "end" as const,
        align: "end" as const,
        color: "#333",
        font: { weight: "bold" as const },
        formatter: (value: number) => value,
      },
      tooltip: {
        callbacks: {
          label: function (context: any) {
            const idx = context.dataIndex;
            const p = productos[idx];
            return [
              `Cantidad: ${p.cantidad_total_vendida}`,
              `Código: ${p.codigoIndumentaria}`,
              `Talle: ${p.talle}`,
              `Tela: ${p.tela}`,
              `Color: ${p.color}`,
            ];
          },
        },
      },
    },
    scales: {
      x: {
        title: {
          display: true,
          text: "Cantidad Total",
          font: { size: 14 },
        },
        beginAtZero: true,
        // Ajuste para que el eje X muestre siempre 1 más que el máximo
        max: Math.max(...productos.map((p) => p.cantidad_total_vendida), 0) + 1,
        ticks: { precision: 0 },
      },
      y: {
        title: {
          display: true,
          text: "Producto",
          font: { size: 14 },
        },
      },
    },
  };

  // Exportar a Excel con gráfico de barras de productos más pedidos
  const exportarExcel = async () => {
    const workbook = new ExcelJS.Workbook();
    workbook.creator = "Pegasus System";
    workbook.created = new Date();

    // Hoja de Productos con columnas correctas y estilos profesionales
    const wsProductos = workbook.addWorksheet("Productos más pedidos");

    // --- LOGO ---
    // Aquí puedes agregar tu logo institucional (PNG base64 o buffer)
    const logoId = workbook.addImage({
      base64:
        "data:image/png;base64,",
      extension: "png",
    });
    wsProductos.addImage(logoId, {
      tl: { col: 0, row: 0 },
      ext: { width: 80, height: 60 },
    });
    // Ajustar altura de filas para que el logo no tape el título ni la fecha
    wsProductos.getRow(1).height = 42;
    wsProductos.getRow(2).height = 28;
    // --- FIN LOGO ---

    // Fila de título grande y centrado
    wsProductos.mergeCells("A1:F1");
    wsProductos.getCell("A1").value = "Top 10 Productos Más Pedidos";
    wsProductos.getCell("A1").font = {
      bold: true,
      size: 18,
      color: { argb: "FF333333" },
    };
    wsProductos.getCell("A1").alignment = {
      vertical: "middle",
      horizontal: "center",
    };
    wsProductos.getRow(1).height = 28;

    // Fila de fecha
    wsProductos.mergeCells("A2:F2");
    wsProductos.getCell("A2").value = `Fecha de emisión: ${fechaEmision}`;
    wsProductos.getCell("A2").font = {
      italic: true,
      size: 11,
      color: { argb: "FF666666" },
    };
    wsProductos.getCell("A2").alignment = {
      vertical: "middle",
      horizontal: "center",
    };
    wsProductos.getRow(2).height = 20;

    // Definir columnas con ancho, encabezado y tipo
    wsProductos.columns = [
      { header: "Nombre", key: "nombre", width: 25 },
      { header: "Código", key: "codigo", width: 15 },
      {
        header: "Cantidad",
        key: "cantidad",
        width: 12,
        style: { numFmt: "#,##0" },
      },
      { header: "Talle", key: "talle", width: 10, style: { numFmt: "0" } },
      { header: "Tela", key: "tela", width: 15 },
      { header: "Top 10 Productos Más Pedidos", key: "color", width: 15 },
    ];
    // Forzar la fila de encabezado manualmente para evitar errores de visualización
    wsProductos.getRow(3).values = [
      "Nombre",
      "Código",
      "Cantidad",
      "Talle",
      "Tela",
      "Color",
    ];

    // Agregar filas de datos, forzando cantidad y talle como números
    (productos || []).forEach((p: ProductoMasPedido) => {
      wsProductos.addRow({
        nombre: p.nombre_indumentaria,
        codigo: p.codigoIndumentaria,
        cantidad: Number(p.cantidad_total_vendida),
        talle: Number(p.talle),
        tela: p.tela,
        color: p.color,
      });
    });

    // Estilos para el encabezado (ahora fila 3)
    wsProductos.getRow(3).eachCell((cell) => {
      cell.font = { bold: true, color: { argb: "FFFFFFFF" }, size: 12 };
      cell.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFFAA61A" }, // Naranja profesional
      };
      cell.alignment = { vertical: "middle", horizontal: "center" };
      cell.border = {
        top: { style: "medium", color: { argb: "FFAAAAAA" } },
        left: { style: "medium", color: { argb: "FFAAAAAA" } },
        bottom: { style: "medium", color: { argb: "FFAAAAAA" } },
        right: { style: "medium", color: { argb: "FFAAAAAA" } },
      };
    });
    wsProductos.getRow(3).height = 22;

    // Estilos para las filas de datos (desde la fila 4)
    wsProductos.eachRow((row, rowNumber) => {
      if (rowNumber <= 3) return; // Saltar título, fecha y encabezado
      row.height = 20;
      row.eachCell((cell, colNumber) => {
        // Alternar color de fondo para filas
        cell.fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: rowNumber % 2 === 0 ? "FFFFFFFF" : "FFF7F7F7" },
        };
        cell.font = { size: 11, color: { argb: "FF333333" } };
        cell.alignment = { vertical: "middle", horizontal: "center" };
        cell.border = {
          top: { style: "thin", color: { argb: "FFCCCCCC" } },
          left: { style: "thin", color: { argb: "FFCCCCCC" } },
          bottom: { style: "thin", color: { argb: "FFCCCCCC" } },
          right: { style: "thin", color: { argb: "FFCCCCCC" } },
        };
      });
    });

    // Pie de página profesional
    /*const lastRow = wsProductos.lastRow?.number || productos.length + 3;
    const pieRowNum = lastRow + 2;
    wsProductos.mergeCells(`A${pieRowNum}:F${pieRowNum}`);
    wsProductos.getCell(`A${pieRowNum}`).value =
      "Reporte generado por Pegasus System | www.pegasus.com.ar";
    wsProductos.getCell(`A${pieRowNum}`).font = {
      italic: true,
      size: 10,
      color: { argb: "FF888888" },
    };
    wsProductos.getCell(`A${pieRowNum}`).alignment = {
      vertical: "middle",
      horizontal: "right",
    };*/

    // Exportar gráfico como imagen (si existe)
    if (chartRef.current) {
      let chartInstance = chartRef.current.chartInstance || chartRef.current;
      if (chartInstance && chartInstance.toBase64Image) {
        const imgBase64 = chartInstance.toBase64Image();
        // Convertir base64 a ArrayBuffer
        const base64Data = imgBase64.replace(/^data:image\/png;base64,/, "");
        const binaryString = atob(base64Data);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        const arrayBuffer = bytes.buffer;
        // Agregar imagen a ExcelJS
        const imageId = workbook.addImage({
          buffer: arrayBuffer,
          extension: "png",
        });
        // Insertar imagen debajo de la tabla (A productos.length+3 para dejar espacio)
        wsProductos.addImage(imageId, {
          tl: { col: 0, row: productos.length + 3 },
          ext: { width: 1000, height: 600 },
        });
      }
    }

    // Descargar archivo
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `productos_mas_pedidos_${new Date()
      .toISOString()
      .slice(0, 10)}.xlsx`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  const exportarPDF = async () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    const title = "Top 10 Productos Más Pedidos";
    const textWidth = doc.getTextWidth(title);
    const x = (pageWidth - textWidth) / 2;

    // Logo en base64 (puedes usar tu propio logo)
    const logoBase64 =
      "data:image/png;base64,";

    doc.addImage(logoBase64, "PNG", 10, 8, 15, 15);
    doc.text(title, x, 18);
    doc.setFontSize(10);
    doc.text(`Fecha de emisión: ${fechaEmision}`, x, 25);

    // Tabla primero
    autoTable(doc, {
      head: [["Nombre", "Código", "Cantidad", "Talle", "Tela", "Color"]],
      body: productos.map((p) => [
        p.nombre_indumentaria,
        p.codigoIndumentaria,
        p.cantidad_total_vendida,
        p.talle,
        p.tela,
        p.color,
      ]),
      startY: 32,
      styles: { fontSize: 10, halign: "center" },
      headStyles: { fillColor: [254, 175, 0], halign: "center" },
    });

    // Gráfico debajo de la tabla
    if (incluirGrafico && chartRef.current) {
      const chart = chartRef.current;
      const chartInstance = chart.chartInstance || chart;
      const imgData = chartInstance.toBase64Image();
      const finalY = (doc as any).lastAutoTable.finalY || 32;
      doc.addImage(imgData, "PNG", 15, finalY + 10, 180, 50);
    }

    doc.save("Productos_mas_pedidos.pdf");
  };

  return (
    <IonPage>
      <IonHeader>
        <IonToolbar color="warning">
          <IonTitle>Productos más pedidos</IonTitle>
        </IonToolbar>
      </IonHeader>
      <IonContent className="ion-padding">
        <IonGrid>
          <IonRow>
            <IonCol size="12" className="ion-text-center">
              <h2 className="reporte-titulo">Top 10 Productos Más Pedidos</h2>
              <div className="reporte-fecha">
                Fecha de emisión: {fechaEmision}
              </div>
            </IonCol>
          </IonRow>
          <IonRow>
            <IonCol size="12">
              <IonCard>
                <IonCardContent>
                  <IonGrid>
                    <IonRow className="table-header">
                      <IonCol size="2" className="celda-centrada">
                        Nombre
                      </IonCol>
                      <IonCol size="2" className="celda-centrada">
                        Código
                      </IonCol>
                      <IonCol size="2" className="celda-centrada">
                        Cantidad
                      </IonCol>
                      <IonCol size="2" className="celda-centrada">
                        Talle
                      </IonCol>
                      <IonCol size="2" className="celda-centrada">
                        Tela
                      </IonCol>
                      <IonCol size="2" className="celda-centrada">
                        Color
                      </IonCol>
                    </IonRow>
                    {productos.map((p, idx) => (
                      <IonRow
                        key={
                          p.codigoIndumentaria +
                          "-" +
                          p.talle +
                          "-" +
                          p.tela +
                          "-" +
                          p.color
                        }
                      >
                        <IonCol size="2" className="celda-centrada">
                          {p.nombre_indumentaria}
                        </IonCol>
                        <IonCol size="2" className="celda-centrada">
                          {p.codigoIndumentaria}
                        </IonCol>
                        <IonCol size="2" className="celda-centrada">
                          {p.cantidad_total_vendida}
                        </IonCol>
                        <IonCol size="2" className="celda-centrada">
                          {p.talle}
                        </IonCol>
                        <IonCol size="2" className="celda-centrada">
                          {p.tela}
                        </IonCol>
                        <IonCol size="2" className="celda-centrada">
                          {p.color}
                        </IonCol>
                      </IonRow>
                    ))}
                    <hr />
                    <IonButton
                      color="primary"
                      size="small"
                      style={{ marginBottom: 8, marginRight: 8 }}
                      onClick={exportarExcel}
                    >
                      <IonIcon icon={downloadOutline} slot="start" />
                      Exportar a Excel
                    </IonButton>
                    <IonButton
                      size="small"
                      fill={incluirGrafico ? "solid" : "outline"}
                      color={incluirGrafico ? "primary" : "medium"}
                      onClick={() => setIncluirGrafico((prev) => !prev)}
                      style={{ marginLeft: 0, marginBottom: 8 }}
                    >
                      {incluirGrafico
                        ? "Quitar gráfico del PDF"
                        : "Incluir gráfico en PDF"}
                    </IonButton>
                    <IonButton
                      color="primary"
                      size="small"
                      className="reporte-btn-pdf"
                      onClick={exportarPDF}
                      style={{ marginTop: 8, marginBottom: 16 }}
                    >
                      <IonIcon icon={documentText} slot="start" />
                      PDF
                    </IonButton>
                  </IonGrid>
                  {/* Gráfico de barras horizontales */}
                  <div
                    style={{
                      background: "white",
                      borderRadius: 12,
                      padding: 40,
                      marginTop: 24,
                    }}
                  >
                    <Bar
                      ref={chartRef}
                      data={data}
                      options={options}
                      plugins={[ChartDataLabels]}
                      width={1200}
                      height={600}
                    />
                  </div>
                </IonCardContent>
              </IonCard>
            </IonCol>
          </IonRow>
        </IonGrid>
      </IonContent>
    </IonPage>
  );
};

export default ProductosMasPedidos;
